// Fail an agent PR that changes the checks it is judged by. Human PRs are not limited here.
import { matchesGlob } from "node:path";
import { isDeepStrictEqual } from "node:util";
import { parse } from "smol-toml"; // a small TOML parser: compare parsed sections, not text

const AGENT_BOTS = new Set(["rhino-ai-agents[bot]"]);
const LOCKED = [ // fcp's block of settings/protected-paths.yaml (G3-21's hooks read it too), inline here to read
  ".github/**", // workflows, scripts, the PR template
  ".claude/settings.json", "scripts/claude_stop_verify.sh", "scripts/poe_verify.py", "frontend/scripts/verify.ts", // verify (G7)
  ".flake8", ".pre-commit-config.yaml",
  "frontend/biome.json", "frontend/tsconfig.json", "frontend/vitest.config.js",
  "frontend/playwright.config.ts", "frontend/stryker.config.mjs",
  "cloud/.coveragerc", "client/rhinoOnPrem/.coveragerc", "sdk/.coveragerc", "sdk/tox.ini",
];
const LOCKED_TOOL_SECTIONS = ["black", "isort", "flake8", "coverage", "pytest"];
const PLAN_BLOCK = /<!-- ai-agents:locked-checks\n([\s\S]*?)\n-->/; // written by the orchestrator (G4)

type ReadFile = (path: string, sha: string) => Promise<string>; // file content at a commit, through Octokit
interface Pr { user: { login: string }; body: string | null; base: { sha: string }; head: { sha: string } }

export async function violations(pr: Pr, files: string[], readFile: ReadFile): Promise<string[]> {
  if (!AGENT_BOTS.has(pr.user.login)) return [];
  const block = PLAN_BLOCK.exec(pr.body ?? "")?.[1];
  const locked = [...LOCKED, ...(block?.split(/\s+/).filter(Boolean) ?? [])];
  const bad = files.filter((f) => locked.some((pattern) => matchesGlob(f, pattern)));
  if (files.includes("pyproject.toml")) { // dependencies may change; lint and test settings may not
    const tool = async (sha: string) => (parse(await readFile("pyproject.toml", sha)).tool ?? {}) as Record<string, unknown>;
    const [base, head] = await Promise.all([tool(pr.base.sha), tool(pr.head.sha)]);
    bad.push(...LOCKED_TOOL_SECTIONS.filter((s) => !isDeepStrictEqual(base[s], head[s])).map((s) => `pyproject.toml [tool.${s}]`));
  }
  return bad; // non-empty: the job fails and lists each file; a person can take the PR over
}

// Call out test edits that make tests easier to pass. Annotations only: editing tests is allowed.
const TEST_PATH = /(^|\/)(tests?|e2e|integration-tests)\/|\.(test|spec)\.tsx?$|(^|\/)test_[^/]+\.py$/;
const ASSERTION = /\bexpect\(|\bassert\b|self\.assert\w+\(|pytest\.raises\(|toThrow|toHaveBeenCalled/;
const SKIP_OR_FOCUS =
  /\b(it|test|describe)\.(skip|todo|fixme|only)\(|\bx(it|describe)\(|@pytest\.mark\.(skip|xfail)|@unittest\.skip/;
const THRESHOLD = /(fail[_-]under|thresholds?|retries|timeout)\W+([\d.]+)/i;
export type Finding = [kind: string, text: string];
export function findings(path: string, patch: string): Finding[] {
  const out: Finding[] = [];
  let removed = 0;
  let added = 0;
  for (const line of patch.split("\n")) {
    const [sign, text] = [line.slice(0, 1), line.slice(1)];
    if ((sign !== "+" && sign !== "-") || line.startsWith("+++") || line.startsWith("---")) continue;
    if (TEST_PATH.test(path) && ASSERTION.test(text)) {
      if (sign === "-") removed += 1;
      else added += 1;
    }
    if (sign === "+" && SKIP_OR_FOCUS.test(text)) out.push(["new skip or focus", text.trim()]);
    if (sign === "-" && THRESHOLD.test(text)) out.push(["threshold changed: check it was not loosened", text.trim()]);
  }
  if (removed > added) out.push(["assertions removed", `${removed - added} more assertions removed than added`]);
  return out; // printed as ::warning file=<path>:: lines plus a job summary
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { violations } from "../src/locked-checks.js";
import { findings } from "../src/weakened-tests.js";

const BASE = '[tool.black]\nline-length = 120\n[project]\ndependencies = ["django==5.2"]\n';
const HEAD = '[tool.black]\nline-length = 120\n[project]\ndependencies = ["django==5.3"]\n';
const readFile = async (_path: string, sha: string) => (sha === "base" ? BASE : HEAD);
const pr = { user: { login: "rhino-ai-agents[bot]" }, body: null, base: { sha: "base" }, head: { sha: "head" } };

test("a human PR is never limited", async () => {
  assert.deepEqual(await violations({ ...pr, user: { login: "sean" } }, [".github/workflows/ci.yml"], readFile), []);
});

test("an agent PR that edits a workflow fails; a dependency bump passes", async () => {
  assert.deepEqual(await violations(pr, [".github/workflows/ci.yml", "pyproject.toml"], readFile), [".github/workflows/ci.yml"]);
});

test("a removed expect and a new skip are called out", () => {
  const patch = "@@ -1,3 +1,3 @@\n-  expect(rows).toHaveLength(3)\n+  it.skip(\"rows\", () => {})\n   const x = 1";
  assert.deepEqual(findings("frontend/test/unit/rows.test.ts", patch), [
    ["new skip or focus", 'it.skip("rows", () => {})'],
    ["assertions removed", "1 more assertions removed than added"],
  ]);
});
